import subprocess
from taf.sw.dcap.rd import rd
from ta5g_interface_tools.robot_variables import get_robot_output_dir


class Ta5gDcap(object):

    def __init__(self):
        self._dcap_object = rd()

    @staticmethod
    def get_testline_ip():
        """
        This method checks test line IP address.
        :return: Test line IP address.
        """
        find_ip_command = "/sbin/ip -o -4 addr list eth0 | awk '{print $4}' | cut -d/ -f1"
        testline_ip = subprocess.check_output(find_ip_command, shell=True).decode(encoding='ASCII').strip()
        return testline_ip

    @staticmethod
    def _resolve_admin_password(admin_username=None, admin_password=None):
        """
        A method used to resolve admin login credentials.
        It returns the default 'Nemuadmin' username and 'nemuuser' password if none is provided.
        """
        if not admin_username:
            admin_username = 'Nemuadmin'
        if not admin_password:
            admin_password = 'nemuuser'
        return admin_username, admin_password

    @staticmethod
    def _resolve_dcap_password(dcap_username=None, dcap_password=None):
        """
        A method used to resolve DCAP login credentials.
        It returns the default 'dcapuser' username and 'dcapadmin!' password if none is provided.
        """
        if not dcap_username:
            dcap_username = 'dcapuser'
        if not dcap_password:
            dcap_password = 'dcapadmin!'
        return dcap_username, dcap_password

    @staticmethod
    def _resolve_output_dir(output_dirpath=None):
        """
        A method used to provide output directory for the DCAP tracing logs. If none is provided,
        the path to test output directory will be returned.
        """
        if not output_dirpath:
            output_dirpath = get_robot_output_dir()
        return output_dirpath

    def configure_dcap_session(self, host=None, port='9443', dcap_username=None, dcap_password=None,
                               rd_version='dcapv3', secure=True, alias=None):
        """
        This method configures DCAP session.
        :param host: IP address to proper host.
        :param port: Port for DCAP connection. '9443' by default.
        :param dcap_username: DCAP username. If not provided (default value 'None') - the username 'dcapuser' will
            be used.
        :param dcap_password: DCAP password. If not provided (default value 'None') - the password 'dcapadmin!' will
            be used.
        :param rd_version: RD version used in the library. 'dcapv3' by default.
        :param secure: Type of DCAP connection. Set to 'True' to use https prefix, set to 'False' to use http prefix.
            'True' by default.
        :param alias:
        """
        if not host:
            host = self.get_testline_ip()
        self._dcap_object.connect_to(host=host, port=port, username=dcap_username, password=dcap_password,
                                     rd_version=rd_version, secure=secure, alias=alias)

    def create_dcap_bts(self, host=None, port='443', admin_username=None, admin_password=None,
                        bts_alias='target_bts', connection=None, timeout=30):
        """
        This method adds a BTS under created DCAP instance.
        :param host: BTS M-plane IP address.
        :param port: Connection port, '443' by default.
        :param admin_username:  admin username. If not provided (default value 'None') - the username 'Nemuadmin' will
            be used.
        :param admin_password: admin password. If not provided (default value 'None') - the password 'nemuuser' will
            be used.
        :param bts_alias: Alias for BTS. 'target_bts' by default.
        :param connection: Unique identifier of a connection.
        :param timeout: Timeout in seconds for the request, 30s by default.
        """
        if not host:
            host = '10.0.1.2'
        admin_username, admin_password = self._resolve_admin_password(admin_username, admin_password)
        self._dcap_object.create_bts(host=host, port=port, username=admin_username, password=admin_password,
                                     bts_alias=bts_alias, connection=connection, timeout=timeout)

    def delete_dcap_bts(self, bts_id=None, connection=None, timeout=30):
        """
        This method deletes BTS instance created under DCAP.
        :param bts_id: BTS_ID of BTS which shall be deleted.
        :param connection: Unique identifier of a connection.
        :param timeout: Timeout for the request, 30s by default.
        """
        self._dcap_object.delete_bts(bts_id=bts_id, connection=connection, timeout=timeout)

    def start_dcap_tracing(self, bts_alias='target_bts', host=None, port='443',
                           admin_username=None, admin_password=None, gnb_trace_profile='dcap-lite-default',
                           enb_trace_profile='dcap-lite-default', bts_trace_profile='dcap-lite-default',
                           duration=-1):
        """
        This method starts collecting traces under DCAP.
        :param bts_alias: Alias for BTS set in 'create_dcap_bts' method.
        :param host: BTS M-plane IP address.
        :param port: Port for DCAP traces. '443' by default.
        :param admin_username: Admin username for BTS. If none is provided, value 'Nemuadmin' will be used.
        :param admin_password: Admin password for BTS. If none is provided, value 'nemuuser' will be used.
        :param gnb_trace_profile: Name for gNB tracing profile. 'dcap-lite-default' by default.
        :param enb_trace_profile: Name for eNB tracing profile. 'dcap-lite-default' by default.
        :param bts_trace_profile: Name for BTS tracing profile. 'dcap-lite-default' by default.
        :param duration: Duration of tracing process, default is -1 (that means it will run until a stop command
            is called).
        """
        if not host:
            host = '10.0.1.2'
        admin_username, admin_password = self._resolve_admin_password(admin_username, admin_password)
        bts_dict = {'alias': bts_alias, 'host': host, 'port': port, 'username': admin_username,
                    'password': admin_password}
        self._dcap_object.start_trace(bts=bts_dict, gnb_trace_profile=gnb_trace_profile,
                                      enb_trace_profile=enb_trace_profile, bts_trace_profile=bts_trace_profile,
                                      duration=duration, wait_for_activation=True, allow_start_failures=True)

    def start_dcap(self, bts_alias='target_bts', host=None, testline_ip=None, configuration_port='9443', port='443',
                   admin_username=None, admin_password=None, dcap_username=None, dcap_password=None,
                   connection=None, rd_version='dcapv3', secure=True, alias=None,
                   timeout=30, duration=-1, gnb_trace_profile='dcap-lite-default',
                   enb_trace_profile='dcap-lite-default', bts_trace_profile='dcap-lite-default'):
        """
        A collective method to configure the DCAP session, create a connection to a BTS and start the tracing.
        It combines 3 methods into one: configure_dcap_session, create_dcap_bts and start_dcap_tracing.
        :param bts_alias: Alias for the BTS. 'target_bts' by default.
        :param host: IP address to the proper host.
        :param testline_ip: IP address of the testline, it is resolved automatically if none is provided (defaut value is None)
        :param configuration_port: Port for DCAP connection, '9443' by default.
        :param port: Port for DCAP traces, '443' by default.
        :param admin_username: Admin username for BTS. If none is provided, value 'Nemuadmin' will be used.
        :param admin_password: Admin password for BTS. If none is provided, value 'nemuuser' will be used.
        :param dcap_username: DCAP username. If not provided (default value 'None') - the username 'dcapuser' will
            be used.
        :param dcap_password: DCAP password. If not provided (default value 'None') - the password 'dcapadmin!' will
            be used.
        :param connection: Unique identifier of a connection.
        :param rd_version: RD version used in the library. 'dcapv3' by default.
        :param secure: Type of DCAP connection. Set to 'True' to use https prefix, set to 'False' to use http prefix.
            'True' by default.
        :param alias:
        :param timeout: Timeout for the request, 30s by default.
        :param duration: Duration of tracing process, default is -1 (that means it will run until a stop command
            is called).
        :param gnb_trace_profile: Name for gNB tracing profile. 'dcap-lite-default' by default.
        :param enb_trace_profile: Name for eNB tracing profile. 'dcap-lite-default' by default.
        :param bts_trace_profile: Name for BTS tracing profile. 'dcap-lite-default' by default.
        """
        self.configure_dcap_session(host=testline_ip, port=configuration_port, dcap_username=dcap_username,
                                    dcap_password=dcap_password, rd_version=rd_version, secure=secure, alias=alias)
        self.create_dcap_bts(host=host, port=port, admin_username=admin_username, admin_password=admin_password,
                             bts_alias=bts_alias, connection=connection, timeout=timeout)
        self.start_dcap_tracing(bts_alias=bts_alias, host=host, port=port, gnb_trace_profile=gnb_trace_profile,
                                enb_trace_profile=enb_trace_profile, bts_trace_profile=bts_trace_profile,
                                admin_username=admin_username, admin_password=admin_password, duration=duration)

    def stop_dcap(self, trace_id=None, connection=None, timeout=400):
        """
        This method stops collecting DCAP traces.
        :param trace_id: Trace ID which shall be stopped.
        :param connection: Unique identifier of a connection.
        :param timeout: Timeout for the request, 300s by default.
        """
        self._dcap_object.stop_trace(trace_id=trace_id, connection=connection, timeout=timeout)

    def get_dcap_results(self, result_id=None, output_dirpath=None, connection=None, timeout=3000):
        """
        This method downloads DCAP traces (logs).
        :param result_id: Result ID of tracing which shall be downloaded.
        :param output_dirpath: Directory to which the logs should be downloaded. If 'None' is provided, the default
            test run output directory will be used.
        :param connection: Unique identifier of a connection.
        :param timeout: Timeout for the request, 3000s by default.
        :param error_msg: Error message which shall be printed when failure occurs.
        """
        output_dirpath = self._resolve_output_dir(output_dirpath)
        self._dcap_object.get_results(result_id=result_id, target_dir=output_dirpath, connection=connection,
                                      timeout=timeout)

    def stop_and_revert_dcap(self, trace_id=None, connection=None, timeout=3000, result_id=None, output_dirpath=None,
                             bts_id=None):
        """
        It's a collective method that combines 3 steps: stopping DCAP tracing, downloading the results (DCAP tracing logs) and deleting
        the BTS instance. It executes 3 methods: stop_dcap, get_dcap_results, delete_dcap_bts.
        :param trace_id: Trace ID which shall be stopped.
        :param connection: Unique identifier of a connection.
        :param timeout: Timeout for the request, 3000s by default.
        :param result_id: Result ID of tracing which shall be downloaded.
        :param output_dirpath: Directory to which the logs should be downloaded. If 'None' is provided, the default test run output directory
            will be used.
        :param error_msg: Error message which shall be printed when failure occurs.
        :param bts_id: BTS_ID of BTS which shall be deleted.
        """
        self.stop_dcap(trace_id=trace_id, connection=connection, timeout=timeout)
        self.get_dcap_results(result_id=result_id, output_dirpath=output_dirpath,
                              connection=connection, timeout=timeout)
        self.delete_dcap_bts(bts_id=bts_id, connection=connection, timeout=timeout)

    def abort_dcap_tracing(self, trace_id=None, connection=None, timeout=30):
        """
        This method aborts DCAP tracing. Logs are permanently deleted.
        :param trace_id: Trace ID which shall be aborted.
        :param connection: Unique identifier of a connection.
        :param timeout: Timeout for the request, 30s by default.
        """
        self._dcap_object.abort_trace(trace_id=trace_id, connection=connection, timeout=timeout)
